Alcotest.run "Double" [
  "arithmetic", [
    Alcotest.test_case "Positive number" `Quick (fun () ->
      Alcotest.(check int) "double 3" 6 (double 3));
    Alcotest.test_case "List" `Quick (fun () ->
      Alcotest.(check (list int)) "doubles" [2; 4] (List.map double [1; 2]));
    Alcotest.test_case "Expected error" `Quick (fun () ->
      Alcotest.check_raises "invalid argument" (Invalid_argument "demo")
        (fun () -> invalid_arg "demo"));
    Alcotest.test_case "Work in progress" `Quick (fun () -> Alcotest.skip ());
  ]
];;
